import sys
from functools import lru_cache

s = sys.stdin.readline().strip()

@lru_cache(None)
def dp(pos, mask, tight, started):
    if pos == len(s):
        return int(started)

    limit = int(s[pos]) if tight else 9
    total = 0

    for digit in range(limit + 1):
        next_tight = tight and digit == limit

        if not started and digit == 0:
            total += dp(pos + 1, mask, next_tight, False)
        else:
            next_mask = mask | (1 << digit)
            if next_mask.bit_count() <= 2:
                total += dp(pos + 1, next_mask, next_tight, True)

    return total

print(dp(0, 0, True, False))

